"""This file contains a Class for loading and reading data from Configuration .cfg files"""

import configparser
from collections import OrderedDict
import logging
import builtins

logger = logging.getLogger(__name__)

# Class for reading data from the Squish config files localconfig.cfg and sharedconfig.cfg
class Config():
    mappings = OrderedDict()
    files_loaded = []

    @staticmethod
    def load(config_file):
        try:
            logger.debug("Loading configuration file: " + config_file)
            config = configparser.SafeConfigParser(allow_no_value=True)
            config.readfp(open(config_file))
            #Create a dictionary of dot-notation entries for each section and key pair.
            for section in config.sections():
                for option in config.options(section):
                    Config.mappings[section + "." + option] = config.get(section, option)
                    #logger.debug( section + ":" + option + ":" + config.get(section, option)
            #logger.debug("Configuration mappings loaded: " + str(Config.mappings))
            Config.files_loaded.append(config_file)
            #logger.debug("Config files loaded: " + str(Config.files_loaded))
        except Exception as e:
            logger.exception("Exception loading config: " + str(e))
            print("Exception loading config: " + str(e))

    @staticmethod
    def get(key, default_val=None):
#            Gets a value from the loaded configuration items.
#            If none found returns an empty string unless a default value
#            has been provided to the default_val kw, in which case that value is returned.
        value =""
        try:
            value = Config.mappings[key]
        except KeyError as e:
            logger.exception("Exception getting value from config file: " + str(e))
            
            print("Exception getting value from config file: " + str(e))
            logger.debug("Supplied key not found in config file, using provided default value instead. - " + str(key))
            if default_val != None:
                value = default_val
        return value

    @staticmethod
    def get_as_int(key, default_val=0):
        #Gets a value from the loaded configuration items and
        #casts value to integer before returning.
        try:
            value = builtins.int(Config.mappings[key])
        except Exception as e:
            logger.debug("Supplied key not found in config file, using provided default value instead.")
            value = default_val

        return value

    @staticmethod
    def get_as_bool(key, default_val=False):
        #Gets a value from the loaded configuration items.
        #If none found returns as a int
        try:
            value = Config.mappings[key][0].lower() in ("y","t")
        except Exception as e:
            logger.debug("Supplied key not found in config file, using provided default value instead.")
            value = str(default_val)[0].lower() in ("y","t")
        return value
